#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <atomic>
#include <cstddef>
#include <new>
#include <utility>
#include <type_traits>
#include <stdexcept>
#include <functional>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <list>
#include <map>
#include <unordered_map>

static const char* b2s(bool b) { return b ? "True" : "False"; }

int main() {
    // ① vector：push_back 超出容量 -> 重新分配，全部迭代器/引用失效
    std::vector<int> v;
    v.reserve(4);
    for (int i = 0; i < 4; ++i) v.push_back(i);
    int* p = v.data();
    v.push_back(4);                                  // 4 -> 8，重新分配
    std::cout << "vector buffer moved on realloc=" << b2s(v.data() != p) << "\n";

    // ② vector：容量内 push_back -> 缓冲不动，但 end() 失效
    std::vector<int> w;
    w.reserve(8);
    for (int i = 0; i < 4; ++i) w.push_back(i);
    int* pw = w.data();
    w.push_back(4);
    std::cout << "vector buffer moved within capacity=" << b2s(w.data() != pw) << "\n";

    // ③ list：节点式容器，插入/删除不使其他元素失效
    std::list<int> l{1, 2, 3};
    auto lit = l.begin();
    l.push_back(99);
    l.push_front(0);
    std::cout << "list iterator still points to 1=" << b2s(*lit == 1) << "\n";

    // ④ map：红黑树插入不使已有迭代器失效
    std::map<int, int> m{{1, 10}, {2, 20}};
    auto mit = m.find(1);
    for (int i = 3; i < 50; ++i) m[i] = i * 10;
    std::cout << "map iterator still valid=" << b2s(mit->second == 10) << "\n";

    // ⑤ unordered_map：rehash 使迭代器失效
    std::unordered_map<int, int> um;
    for (int i = 0; i < 4; ++i) um[i] = i;
    std::size_t bucketsBefore = um.bucket_count();
    for (int i = 4; i < 200; ++i) um[i] = i;
    std::cout << "unordered_map rehashed=" << b2s(um.bucket_count() != bucketsBefore) << "\n";

    // ⑥ erase 后原迭代器失效：用 erase 返回值续接
    std::vector<int> d{1, 2, 3, 4};
    auto it = d.begin() + 1;
    it = d.erase(it);                                 // 返回指向下一个元素的有效迭代器
    std::cout << "erase returned next element=" << *it << "\n";
    std::cout << "size after erase=" << d.size() << "\n";
}
